import {parseVnd,formatVndInput,formatMoneyElement,normalizeMoneyFields,applyMoneyEdit} from './money.mjs';
import {RetailCloud} from './cloud.mjs';
import {loginView,organizationsView} from './auth-ui.mjs';
import {analyzeDemand} from './demand.mjs';
import {translateUI,uiLanguage} from './i18n.mjs';
import {fmt,uid,isoDay,validateData,baseState,seedDemo,migrateLegacy,migrateLegacyBackup,productCreate,productEdit,supplierCreate,supplierEdit,customerCreate,customerEdit,createOrder,updateOrderStatus,receiveStock,createPurchaseOrder,purchaseMarkTransit,purchaseReceive,payPurchase,payServiceCharge,payOrder,refundOrder,orderPaid,customerReceivables,supplierDeliveryStats,compareSupplierOffers,auditStock,expenseSave,expenseDelete,decisionSave,financials,procurementSummary,supplierDebt,inventoryValue,monthlyRevenue,salesByProduct,forecast,scoreSuppliers,scenario,goalSeek,simpleRecommendation} from './core.mjs';
// Preserve old local data for demo/backup only; authenticated organizations use isolated Supabase state.
const KEY='smartdecision_v3_main';
const cloud=new RetailCloud();
const runtime={mode:'loading',error:'',tab:'login',organizations:[],busy:false,preview:(typeof process!=='undefined'&&Boolean(process.versions?.node))||new URLSearchParams(globalThis.location?.search||'').get('preview')==='1',saving:0,blocked:false};
let data=baseState();
let saveQueue=Promise.resolve();
const productImages=new Map();
const prefs={lang:localStorage.getItem('retailmind_lang')||'vi',theme:localStorage.getItem('retailmind_theme')||'blue',font:localStorage.getItem('retailmind_font')||'medium'};
function localDemo(){try{const v=JSON.parse(localStorage.getItem(KEY)||'null');return v?validateData(v):seedDemo();}catch{return seedDemo();}}
function applyPreferences(){const root=document.documentElement;if(!root)return;root.dataset.theme=prefs.theme;root.dataset.font=prefs.font;root.lang=prefs.lang;}
async function startCloud(){
 applyPreferences();
 if(runtime.preview){data=localDemo();runtime.mode='preview';return render();}
 if(!cloud.configured){runtime.mode='auth';runtime.error='Thiếu cấu hình Supabase công khai trong Netlify. Vui lòng xem hướng dẫn cài đặt.';return render();}
 try{
  const recovery=new URLSearchParams(location.hash.slice(1));
  if(recovery.get('access_token')&&recovery.get('type')==='recovery'){
   cloud.keepSession({access_token:recovery.get('access_token'),refresh_token:recovery.get('refresh_token'),expires_in:Number(recovery.get('expires_in')||3600)});
   cloud.user=await cloud.request('/auth/v1/user');runtime.mode='reset';history.replaceState(null,'',location.pathname);return render();
  }
  if(await cloud.restore())return await showOrganizations();
  runtime.mode='auth';render();
 }catch(e){runtime.mode='auth';runtime.error=e.message;render();}
}
async function showOrganizations(){runtime.organizations=await cloud.organizations();runtime.mode='choose';runtime.error='';render();}
async function chooseOrganization(id){
 const org=runtime.organizations.find(o=>o.id===id);if(!org)throw Error('Không tìm thấy doanh nghiệp.');
 data=validateData(await cloud.loadOrganization(org));chatEpoch++;ui.chat=[{role:'assistant',text:'Xin chào! Mình có thể hỗ trợ phân tích dữ liệu và phương án của doanh nghiệp này.'}];ui.chatBusy=false;ui.chatInput='';ui.chatOpen=false;runtime.mode='app';runtime.blocked=false;runtime.error='';ui.page='dashboard';productImages.clear();await loadProductImages();render();
}
async function loadProductImages(){if(!cloud.org)return;await Promise.all((data.products||[]).filter(p=>p.imagePath).slice(0,100).map(async p=>{try{productImages.set(p.id,await cloud.fileUrl(p.imagePath));}catch{}}));}
function renderAccount(){const root=document.getElementById('app');root.innerHTML=runtime.mode==='choose'?organizationsView({user:cloud.user,organizations:runtime.organizations,error:runtime.error,loading:runtime.busy}):loginView({tab:runtime.tab,error:runtime.error,configured:cloud.configured,recovery:runtime.mode==='reset'});translateUI(root,prefs.lang);}
async function authAction(form){
 if(runtime.busy)return;runtime.busy=true;runtime.error='';const x=Object.fromEntries(new FormData(form));
 try{
  if(form.id==='auth-entry'){
   if(x.mode==='signup'){if(x.password!==x.confirm)throw Error('Hai mật khẩu chưa trùng nhau.');await cloud.signup(x.email,x.password);runtime.tab='login';runtime.error='Đã gửi email xác minh. Hãy mở email và xác nhận trước khi đăng nhập.';}
   else if(x.mode==='forgot'){await cloud.recover(x.email,location.origin+location.pathname);runtime.tab='login';runtime.error='Nếu email đã đăng ký, hệ thống sẽ gửi liên kết khôi phục.';}
   else if(x.mode==='reset'){await cloud.updatePassword(x.password);runtime.mode='auth';runtime.tab='login';await cloud.logout();runtime.error='Đã đặt lại mật khẩu. Hãy đăng nhập lại.';}
   else {await cloud.login(x.email,x.password);await showOrganizations();return;}
  }else if(form.id==='company-create'){
   const initial=baseState();initial.company.name=x.company.trim();
   const id=await cloud.createOrganization(x.company.trim(),initial);await showOrganizations();await chooseOrganization(id);return;
  }else if(form.id==='company-join'){
   const id=await cloud.joinOrganization(x.code.trim());await showOrganizations();await chooseOrganization(id);return;
  }
 }catch(e){runtime.error=e.message||'Có lỗi xử lý tài khoản.';}
 finally{runtime.busy=false;render();}
}
let chatEpoch=0;
const ui={compareProduct:'',compareQty:20,page:'dashboard',filter:'',month:'all',forecastProduct:'',scenario:{pricePct:5,unitsPct:-3,costPct:0,expensesPct:0},goal:10000000,modal:'',editing:'',sidebar:false,chatOpen:false,chatInput:'',chatBusy:false,chat:[{role:'assistant',text:'Xin chào! Bạn muốn phân tích doanh thu, tồn kho, công nợ hay so sánh phương án kinh doanh?'}],chatPos:null};
try {ui.chatPos=JSON.parse(localStorage.getItem('smartdecision_v3_chatpos')||'null');ui.chatFabPos=JSON.parse(localStorage.getItem('smartdecision_v4_chatfabpos')||'null');}catch{}
const navColors={dashboard:'#62b5ff',orders:'#ff879e',products:'#ffbd68',inventory:'#78b2ff',suppliers:'#50dbc8',customers:'#83c5ff',finance:'#5ce3aa',analytics:'#c99bff',forecast:'#55d0f5',scenarios:'#ffc164',ranking:'#fa91c2',decisions:'#ac92ff',settings:'#aab9d2'};
const nav=[{group:'VẬN HÀNH',items:[['dashboard','▦','Tổng quan'],['orders','▤','Bán hàng & đơn hàng'],['products','◈','Danh mục sản phẩm'],['inventory','▣','Kho & kiểm kê'],['suppliers','♧','Nhà cung cấp & nhập hàng'],['customers','♙','Khách hàng'],['finance','◉','Tài chính & báo cáo']]},{group:'HỖ TRỢ RA QUYẾT ĐỊNH',items:[['analytics','▥','Phân tích kinh doanh'],['forecast','⌁','Dự báo nhu cầu'],['scenarios','◇','Mô phỏng quyết định'],['ranking','⚖','So sánh nhà cung cấp'],['decisions','◎','Theo dõi quyết định']]},{group:'HỆ THỐNG',items:[['settings','⚙','Cài đặt doanh nghiệp']]}];
const titles={...Object.fromEntries(nav.flatMap(g=>g.items.map(i=>[i[0],i[2]]))),alerts:'Cảnh báo cần xử lý'};
const safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const integer=x=>new Intl.NumberFormat('vi-VN').format(Number(x)||0);
const productName=id=>data.products.find(p=>p.id===id)?.name||'Sản phẩm đã xóa';
const supplierName=id=>data.suppliers.find(x=>x.id===id)?.name||'Không xác định';
const supplierPolicies=sup=>sup?.shippingPolicy==='threshold'?`Miễn phí khi đạt ${money(sup.freeThreshold||0)}`:sup?.shippingPolicy==='free'?'Giao miễn phí':sup?.shippingPolicy==='supplier'?'Giao có phí':sup?.shippingPolicy==='external'?'Thuê vận chuyển riêng':'Chưa có chính sách';
const delivered=p=>['Đã nhận','Nhận thiếu','Từ chối nhận'].includes(p.deliveryStatus)||!p.deliveryStatus;
const outstandingCharges=()=>data.purchases.flatMap(p=>(p.charges||[]).filter(c=>c.amount>c.paid).map(c=>({...c,purchaseId:p.id,purchase:p})));

const customerName=id=>data.customers.find(x=>x.id===id)?.name||'Khách hàng cũ';
const money=x=>fmt(x);
const badge=(s)=>{const tone=/(Hoàn thành|Đã duyệt|Đủ hàng)/.test(s)?'ok':/(Đã hủy|Hủy|Thiếu hàng|Quá hạn)/.test(s)?'bad':'warn';return `<span class="status status-${tone}">${safe(s)}</span>`;};
const btn=(text,act,cls='secondary',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${act}" ${attrs}>${text}</button>`;
const date=s=>{if(!s)return '—';if(/^\d{4}-\d{2}-\d{2}/.test(s)){const [y,m,d]=s.slice(0,10).split('-');return `${d}/${m}/${y}`;}return safe(s);};
const card=(label,val,desc,icon='◇',tone='blue')=>`<div class="metric"><div class="metric-icon ${tone}">${icon}</div><div class="metric-label">${label}</div><strong>${val}</strong><small>${desc||'Theo dữ liệu hiện có'}</small></div>`;
const panel=(title,body,aside='')=>`<section class="panel"><div class="panel-title"><h2>${title}</h2>${aside}</div>${body}</section>`;
const empty=(t='Chưa có dữ liệu phù hợp.')=>`<div class="empty">⌁<p>${safe(t)}</p></div>`;
const td=x=>`<td>${x}</td>`;
const table=(headers,rows)=>`<div class="table-scroll"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}">${empty()}</td></tr>`}</tbody></table></div>`;
const tableRow=c=>`<tr>${c.map(td).join('')}</tr>`;
const company=()=>safe(data.company.name||'Doanh nghiệp chưa đặt tên');
function setData(v,toast='Đã lưu thay đổi.') {
 if(runtime.mode!=='app' && runtime.mode!=='preview')throw Error('Cần chọn doanh nghiệp để ghi dữ liệu.');
 if(runtime.blocked)throw Error('Đã phát hiện thay đổi dữ liệu trên thiết bị khác; cần tải lại trang trước khi tiếp tục.');
 data=validateData(v);
 if(runtime.preview){try{localStorage.setItem(KEY,JSON.stringify(data));}catch{}render();notice('Đã lưu bản xem thử trên trình duyệt (không đồng bộ).');return;}
 const snapshot=structuredClone(data);runtime.saving++;render();notice(toast+' · Đang đồng bộ…');
 saveQueue=saveQueue.then(()=>cloud.saveState(snapshot)).then(()=>{runtime.saving--;updateSyncIndicator();}).catch(async error=>{
  runtime.saving=Math.max(0,runtime.saving-1);runtime.blocked=true;
  try{data=validateData(await cloud.loadOrganization(cloud.org));await loadProductImages();}catch{}
  render();notice('Không lưu được: '+(error.message||error)+'. Đã tải lại dữ liệu gần nhất; vui lòng kiểm tra trước khi thao tác tiếp.','bad');
 });
}
function updateSyncIndicator(){const e=document.getElementById('sync-status');if(e)e.textContent=runtime.saving?'● Đang đồng bộ':'● Đã đồng bộ';}

function notice(message,tone='ok'){const t=document.getElementById('toast');if(!t)return;t.className=`toast show ${tone}`;t.textContent=message;clearTimeout(notice.timer);notice.timer=setTimeout(()=>{t.className='toast';},4400);}
let lastMutationOk=true;function transactional(fn,msg){try{setData(fn(data),msg);lastMutationOk=true;return true;}catch(e){lastMutationOk=false;notice(e.message||'Dữ liệu không hợp lệ.','bad');return false;}}
function main(){
 const f=financials(data),r=simpleRecommendation(data),pr=procurementSummary(data),trend=monthlyRevenue(data,6);
 const max=Math.max(1,...trend.map(x=>x.revenue));
 const overdue=(r.lateDeliveries||[]).length,low=r.low||[],debts=r.debts||[];
 const todo=[
  ...low.slice(0,2).map(p=>({icon:'▣',tone:'orange',title:`${p.name} chạm ngưỡng tồn kho`,detail:`Hiện có ${integer(p.stock)} · Ngưỡng ${integer(p.min)}`,page:'inventory',tag:'Cần kiểm tra'})),
  ...(overdue?[{icon:'◷',tone:'rose',title:`${overdue} phiếu mua giao trễ`,detail:'Xem ngày hẹn và tiến độ nhận hàng',page:'suppliers',tag:'Ưu tiên'}]:[]),
  ...(f.missing.length?[{icon:'!',tone:'purple',title:`${f.missing.length} đơn thiếu giá vốn`,detail:'Lợi nhuận chưa thể xác minh đầy đủ',page:'finance',tag:'Thiếu dữ liệu'}]:[]),
  ...(debts.length?[{icon:'↗',tone:'blue',title:`${debts.length} nhà cung cấp còn công nợ`,detail:'Kiểm tra thời hạn và lịch sử thanh toán',page:'suppliers',tag:'Theo dõi'}]:[])
 ];
 const totalActions=low.length+overdue+f.missing.length+debts.length;
 const top=salesByProduct(data).filter(x=>x.units>0).sort((a,b)=>b.units-a.units).slice(0,4);
 const pending=data.decisions.filter(x=>!/(Hoàn thành|Đã duyệt)/.test(x.status||'')).length;
 const moneyOrNA=f.net===null?'Chưa đủ dữ liệu':money(f.net);
 const kpis=[
  {theme:'blue',icon:'↗',label:'Doanh thu hoàn thành',value:money(f.revenue),detail:`${f.orders} đơn đã hoàn thành`},
  {theme:'violet',icon:'▤',label:'Giá vốn đã xác minh',value:money(f.cogsKnown),detail:`${f.missing.length} đơn còn thiếu giá vốn`},
  {theme:'amber',icon:'▣',label:'Giá trị tồn kho',value:money(inventoryValue(data)),detail:`${data.products.length} mã sản phẩm`},
  {theme:'mint',icon:'◎',label:'Lợi nhuận sau chi phí',value:moneyOrNA,detail:'Chưa bao gồm thuế và lãi vay'}
 ];
 const metricMarkup=kpis.map(z=>`<article class="command-metric tone-${z.theme}"><div class="command-metric-head"><span>${safe(z.label)}</span><span class="command-metric-icon">${z.icon}</span></div><strong>${z.value}</strong><small>${safe(z.detail)}</small><div class="command-metric-decor" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div></article>`).join('');
 const actionMarkup=todo.length?todo.slice(0,4).map((x,i)=>`<button class="action-row" data-go="${x.page}"><span class="action-ordinal tone-${x.tone}">${i+1}</span><span class="action-text"><b>${safe(x.title)}</b><small>${safe(x.detail)}</small></span><span class="action-tag tone-${x.tone}">${safe(x.tag)}</span><span class="action-chevron">›</span></button>`).join(''):'<div class="command-empty"><span>✓</span><strong>Hoạt động ổn định</strong><small>Chưa có vấn đề nào vượt ngưỡng đang cấu hình.</small></div>';
 const trendMarkup=trend.map(x=>`<div class="command-chart-month"><div class="command-chart-track"><i style="height:${Math.max(2,x.revenue/max*100)}%" title="${money(x.revenue)}"></i></div><b>${safe(x.label)}</b><small>${x.revenue?integer(Math.round(x.revenue/1000))+'k':'0'}</small></div>`).join('');
 const topMarkup=top.length?top.map((x,i)=>{const p=data.products.find(p=>p.id===x.productId);return `<div class="top-product-row"><span class="top-product-rank">${i+1}</span><span class="top-product-image">${p?productPhoto(p):'▣'}</span><span class="top-product-info"><b>${safe(x.name)}</b><small>Đã bán ${integer(x.units)} sản phẩm</small></span><strong>${money(x.revenue)}</strong></div>`}).join(''):empty('Chưa có dữ liệu bán theo sản phẩm hợp lệ.');
 return `<section class="command-welcome"><div class="command-welcome-copy"><span class="command-kicker"><span>✦</span> TRUNG TÂM ĐIỀU HÀNH THÔNG MINH</span><h2>Hiểu dữ liệu sâu hơn.<br><em>Ra quyết định tự tin hơn.</em></h2><p>Giám sát hoạt động, phát hiện vấn đề và chuyển từ phân tích sang hành động — trong cùng một không gian làm việc.</p><div class="command-welcome-actions"><button data-go="decisions" class="command-cta">Xem quyết định <span>↗</span></button><button data-go="analytics" class="command-cta secondary">Khám phá số liệu</button></div></div><div class="command-hero-art" aria-hidden="true"><div class="art-ring art-ring-1"></div><div class="art-ring art-ring-2"></div><div class="art-grid"></div><div class="art-card art-card-left"><span>✦</span><b>DATA</b></div><div class="art-bars"><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="art-up">↗</div><div class="art-card art-card-right"><span>◎</span><b>DECISION</b></div></div></section>
 <div class="command-metrics">${metricMarkup}</div>
 <section class="command-grid"><div class="command-focus"><div class="command-section-title"><div><span class="section-icon tone-rose">◎</span><span><h2>Bản đồ quyết định hôm nay</h2><p>Việc cần ưu tiên từ dữ liệu thực tế</p></span></div><span class="command-count">${totalActions} vấn đề</span></div><div class="action-rows">${actionMarkup}</div><div class="command-focus-bottom"><span>Nhấn một vấn đề để đi tới màn hình xử lý</span><button data-go="decisions">Theo dõi quyết định →</button></div></div>
 <aside class="command-side"><div class="command-ai"><div class="command-section-title"><div><span class="section-icon tone-violet">✧</span><span><h2>Trợ lý phân tích AI</h2><p>Gợi ý từ dữ liệu doanh nghiệp</p></span></div></div><p>Hãy yêu cầu Gemini giải thích xu hướng, tìm nguyên nhân và so sánh các phương án. Hệ thống sẽ phân biệt kết quả mô hình với phản hồi AI.</p><button data-chat-prompt="Phân tích các vấn đề kinh doanh ưu tiên của doanh nghiệp từ dữ liệu hiện có, nêu căn cứ và 3 hành động phù hợp, không bịa số liệu." class="command-ai-button">✦ Phân tích cùng AI <span>→</span></button></div><div class="command-decisions"><span class="command-mini-icon">◈</span><span><b>${integer(pending)} quyết định cần theo dõi</b><small>Quản lý mục tiêu, người phụ trách và tiến độ</small></span><button data-go="decisions" aria-label="Mở theo dõi quyết định">→</button></div></aside></section>
 <section class="command-bottom"><div class="command-trends"><div class="command-section-title"><div><span class="section-icon tone-blue">▥</span><span><h2>Doanh thu theo 6 tháng</h2><p>Chỉ tính đơn hoàn thành, không dùng số liệu giả lập</p></span></div><button data-go="finance">Xem tài chính ↗</button></div><div class="command-chart">${trendMarkup}</div></div><div class="command-top-products"><div class="command-section-title"><div><span class="section-icon tone-amber">▣</span><span><h2>Sản phẩm nổi bật</h2><p>Thứ hạng từ số lượng thực bán</p></span></div><button data-go="products">Tất cả →</button></div>${topMarkup}</div></section>
 <div class="command-shortcuts"><div><span class="section-icon tone-mint">✓</span><strong>Thao tác nhanh</strong></div><button data-go="orders">＋ Đơn hàng</button><button data-go="suppliers">＋ Phiếu mua</button><button data-go="forecast">⌁ Dự báo</button><button data-go="scenarios">◇ Mô phỏng</button><button data-go="settings">⚙ Cài đặt</button></div>`;
}

function pageOrders(){const rows=data.orders.filter(o=>search(o.id+' '+o.customerName+' '+o.status));return `${head('Bán hàng & thanh toán','Lập đơn, theo dõi giao dịch và lưu chứng từ thanh toán của khách.',btn('＋ Tạo đơn hàng','new-order','primary'))}<div class="metrics three">${card('Phải thu từ khách',money(customerReceivables(data)),'Đơn hoàn thành chưa thu đủ','◉','orange')}${card('Đơn hàng',integer(data.orders.length),'Toàn bộ trạng thái','▤')}${card('Đã thu từ khách',money(procurementSummary(data).cashReceived),'Theo lịch sử nhận và hoàn tiền','↗','green')}</div>${panel('Danh sách đơn hàng',table(['Mã / ngày','Khách hàng / nơi giao','Sản phẩm','Tổng đơn','Đã thu · Còn thu','Trạng thái','Thao tác'],rows.map(o=>tableRow([`<span class="code">${safe(o.id)}</span><small>${date(o.date)}</small>`,safe(o.customerName||customerName(o.customerId))+`<small>${safe(o.deliveryAddress||'Chưa ghi địa chỉ giao')}</small>`,o.lines?.length?o.lines.map(l=>`${safe(l.name||productName(l.productId))} × ${integer(l.quantity)}`).join('<br>'):'<span class="subtle">Đơn cũ thiếu dòng SKU</span>',`<strong>${money(o.total)}</strong>`,`<strong>${money(orderPaid(o))}</strong><small>${o.total>orderPaid(o)?'Còn phải thu: '+money(Math.max(0,o.total-orderPaid(o))):'Đã thu đủ'}</small>`,badge(o.status),`<select aria-label="Trạng thái đơn hàng" data-order-status="${safe(o.id)}"><option ${o.status==='Đang xử lý'?'selected':''}>Đang xử lý</option><option ${o.status==='Hoàn thành'?'selected':''}>Hoàn thành</option><option ${o.status==='Đã hủy'?'selected':''}>Đã hủy</option></select><div class="row-actions">${o.status!=='Đã hủy'&&orderPaid(o)<o.total?btn('Thu tiền','pay-order','compact',`data-id="${safe(o.id)}"`):''}${orderPaid(o)>0?btn('Hoàn tiền','refund-order','compact',`data-id="${safe(o.id)}"`):''}${btn('Thêm chứng từ','attach-evidence','compact',`data-id="orderproof:${safe(o.id)}"`)}${btn('Xem ảnh','view-evidence','compact',`data-id="orderproof:${safe(o.id)}"`)}</div>`]))))}${panel('Lịch sử nhận tiền & hoàn tiền',table(['Ngày','Đơn hàng','Loại','Số tiền','Phương thức / tham chiếu','Chứng từ'],data.orders.flatMap(o=>[...(o.payments||[]).map(pay=>tableRow([date(pay.date),safe(o.id),'Khách thanh toán',money(pay.amount),safe([pay.method,pay.reference].filter(Boolean).join(' · ')),btn('Xem chứng từ','view-evidence','compact',`data-id="orderpay:${safe(pay.id)}"`)+' '+btn('Bổ sung ảnh/PDF','attach-evidence','compact',`data-id="orderpay:${safe(pay.id)}"`)])),...(o.refunds||[]).map(pay=>tableRow([date(pay.date),safe(o.id),'Hoàn tiền khách',money(pay.amount),safe([pay.method,pay.reference].filter(Boolean).join(' · ')),btn('Xem chứng từ','view-evidence','compact',`data-id="refund:${safe(pay.id)}"`)+' '+btn('Bổ sung ảnh/PDF','attach-evidence','compact',`data-id="refund:${safe(pay.id)}"`)]))])))}<p class="caption">Trạng thái Hoàn thành chỉ ghi nhận việc bán hàng; tiền khách thực trả được ghi riêng. Đơn đã thu tiền phải hoàn đủ trước khi hủy.</p>`;}
function productPhoto(p){const url=productImages.get(p.id)||p.imageData;return url?`<img loading="lazy" src="${safe(url)}" alt="Ảnh ${safe(p.name)}" class="product-thumb">`:`<span class="product-thumb product-placeholder">▣</span>`;}
function pageProducts(){return `${head('Danh mục sản phẩm','Quản lý mã hàng, danh mục, giá bán và giá vốn tự động.',btn('＋ Thêm sản phẩm','new-product','primary'))}${panel('Sản phẩm đang quản lý',table(['Mã SKU','Sản phẩm','Danh mục','Giá bán','Giá vốn bình quân','Nhà cung cấp','Tồn hiện tại','Thao tác'],data.products.filter(p=>search(p.name+' '+p.sku+' '+p.category)).map(p=>tableRow([`<span class="code">${safe(p.sku)}</span>`,`<span class="product-name-cell">${productPhoto(p)}<span><strong>${safe(p.name)}</strong><small>${p.active===false?'Ngừng bán':'Đang bán'}</small></span></span>`,safe(p.category),money(p.price),p.cost?money(p.cost):'<span class="muted">Chưa nhập kho</span>',safe(supplierName(p.supplierId)),integer(p.stock),btn('Sửa','edit-product','compact',`data-id="${safe(p.id)}"`)]))))}<p class="caption">Giá vốn bình quân được tính từ hàng đã nhận; giá vốn trên đơn đã bán được giữ tại thời điểm giao dịch.</p>`;}
function pageInventory(){const low=data.products.filter(p=>p.stock<=p.min&&p.active!==false);return `<div class="metrics three">${card('Sản phẩm đang theo dõi',integer(data.products.length),'SKU trong danh mục','▦')}${card('Giá trị tồn kho',money(inventoryValue(data)),'Giá vốn × tồn hiện tại','◈','green')}${card('Cảnh báo thiếu hàng',integer(low.length),'Tồn không lớn hơn ngưỡng','⚑','orange')}</div>${head('Tồn kho & kiểm kê','Luồng riêng biệt: nhận hàng từ nhà cung cấp, ghi công nợ, điều chỉnh tồn và xem nhật ký.',`${btn('＋ Tạo phiếu nhập tại Nhà cung cấp','go-purchase','primary')} ${btn('Kiểm kê','audit')}`)}${panel('Tồn kho theo SKU',table(['SKU','Sản phẩm','Tồn','Ngưỡng','Trạng thái','Vốn cần bổ sung tới ngưỡng'],data.products.filter(p=>search(p.name+' '+p.sku)).map(p=>tableRow([`<span class="code">${safe(p.sku)}</span>`,safe(p.name),integer(p.stock),integer(p.min),badge(p.stock<=p.min?'Thiếu hàng':'Đủ hàng'),money(Math.max(0,p.min-p.stock)*p.cost)]))))}${panel('Nhật ký nhập / xuất / kiểm kê',table(['Ngày','Nghiệp vụ','Tham chiếu','Biến động','Lý do','Biên bản'],data.stockLedger.slice(0,40).map(x=>tableRow([date(x.date),badge(x.type),`<span class="code">${safe(x.ref)}</span>`,(x.lines||[]).map(l=>`${safe(productName(l.productId))}: ${l.quantity>0?'+':''}${integer(l.quantity)}`).join('<br>'),safe(x.reason||'—'),x.type==='Kiểm kê'?btn('Xem ảnh/PDF','view-evidence','compact',`data-id="audit:${safe(x.id)}"`):'—']))))}`;}
function pageSuppliers(){
 const ps=procurementSummary(data);
 const supplierRows=data.suppliers.filter(s=>search(s.name)).map(s=>{
  const st=supplierDeliveryStats(data,s.id);
  return tableRow([`<strong>${safe(s.name)}</strong><small>${safe(s.id)}</small>`,`${safe(s.type||'Hàng hóa')}<small>${safe(s.phone||s.contact||'—')}</small>`,safe(supplierPolicies(s)),`${integer(s.deliveryDays||0)} ngày`,st.sample?`${st.onTime}/${st.sample} lần (${st.onTimePct}%)`:'<span class="muted">Chưa có dữ liệu</span>',money(supplierDebt(data,s.id)),btn('Sửa','edit-supplier','compact',`data-id="${safe(s.id)}"`)]);
 });
 const purchaseRows=data.purchases.map(p=>tableRow([
  `<span class="code">${safe(p.id)}</span><small>${date(p.date)}</small>`,safe(supplierName(p.supplierId)),safe(productName(p.productId)),`${integer(p.orderedQuantity??p.quantity)} / ${integer(p.quantity||0)}`,`<small>${date(p.expectedDelivery)} / ${date(p.deliveredDate)}</small>`,money(!delivered(p)?p.plannedValue:(p.landedTotal??p.total)),money(Math.max(0,p.total-p.paid)),
  `${badge(p.deliveryStatus||'Đã nhận')}<div class="row-actions">${p.deliveryStatus==='Chờ giao'?btn('Đang giao','mark-transit','compact',`data-id="${safe(p.id)}"`):''}${!delivered(p)?btn('Xác nhận đã nhận','confirm-receipt','compact',`data-id="${safe(p.id)}"`):''}${btn('Hóa đơn','view-evidence','compact',`data-id="purchase:${safe(p.id)}"`)}${delivered(p)?btn('Phiếu giao','view-evidence','compact',`data-id="receipt:${safe(p.id)}"`):''}</div>`
 ]));
 const chargeRows=data.purchases.flatMap(p=>(p.charges||[]).map(c=>tableRow([safe(p.id),safe(supplierName(c.partnerId)),safe(c.kind),money(c.amount),money(c.paid),money(c.amount-c.paid),c.amount>c.paid?btn('Thanh toán','pay-service','compact',`data-id="${safe(p.id)}|${safe(c.id)}"`):'Đã trả'])));
 const paymentRows=data.purchases.flatMap(p=>[
  ...(p.payments||[]).map(pay=>tableRow([date(pay.date),safe(p.id),safe(supplierName(p.supplierId)),money(pay.amount),safe(pay.reference||'—'),btn('Xem chứng từ','view-evidence','compact',`data-id="payment:${safe(pay.id)}"`)+' '+btn('Bổ sung ảnh/PDF','attach-evidence','compact',`data-id="payment:${safe(pay.id)}"`)])),
  ...(p.charges||[]).flatMap(c=>(c.payments||[]).map(pay=>tableRow([date(pay.date),safe(p.id),safe(supplierName(c.partnerId)),money(pay.amount),safe(pay.reference||'—'),btn('Xem chứng từ','view-evidence','compact',`data-id="payment:${safe(pay.id)}"`)+' '+btn('Bổ sung ảnh/PDF','attach-evidence','compact',`data-id="payment:${safe(pay.id)}"`)])))
 ]);
 return `${head('Nhà cung cấp & mua hàng','Theo dõi giao hàng, đặt mua, nhận hàng, công nợ và chứng từ.',`${btn('＋ Thêm đối tác','new-supplier','primary')} ${btn('＋ Tạo phiếu mua','receive','primary')} ${btn('Trả nhà cung cấp','pay')} ${btn('Trả phí dịch vụ','pay-service')} ${btn('Đánh giá nhà cung cấp','go-ranking')}`)}
 <div class="metrics three">${card('Đối tác',integer(data.suppliers.length),'Nhà cung cấp và dịch vụ','♧')}${card('Còn phải trả',money(ps.debtOutstanding+ps.serviceDebt),'Gồm cả phí vận chuyển','◉','orange')}${card('Phiếu mua chờ giao',integer(data.purchases.filter(x=>!delivered(x)).length),'Chưa cộng vào tồn kho','▥')}</div>
 ${panel('Thông tin đối tác',table(['Đối tác','Loại / liên hệ','Chính sách giao','Dự kiến','Đúng hẹn','Công nợ hàng hóa','Sửa'],supplierRows))}
 ${panel('Chứng từ mua hàng · Đơn mua và giao nhận',table(['Mã phiếu','Nhà cung cấp','Sản phẩm','Đặt / nhận','Hẹn / đã giao','Giá trị','Nợ NCC','Trạng thái · Chứng từ'],purchaseRows))}
 ${panel('Công nợ vận chuyển và bốc xếp',table(['Phiếu','Đối tác','Loại phí','Phải trả','Đã trả','Còn nợ','Thao tác'],chargeRows))}
 ${panel('Lịch sử thanh toán & chứng từ',table(['Ngày','Phiếu','Người nhận','Số tiền','Tham chiếu','Chứng từ'],paymentRows))}
 <p class="caption">Chỉ xác nhận nhận hàng khi đã kiểm đếm thực tế. Một lần trả nợ tương ứng một chứng từ riêng.</p>`;
}
function pageCustomers(){return `${head('Khách hàng','Lưu thông tin giao hàng và xem lịch sử mua, công nợ từ đơn hàng.',btn('＋ Thêm khách hàng','new-customer','primary'))}${panel('Danh sách khách hàng & công nợ',table(['Khách hàng','Liên hệ','Địa chỉ mặc định','Tổng đơn','Doanh thu hoàn thành','Còn phải thu','Thao tác'],data.customers.filter(c=>search(c.name+' '+c.phone)).map(c=>{const od=data.orders.filter(o=>o.customerId===c.id);return tableRow([`<strong>${safe(c.name)}</strong><small>${safe(c.id)}</small>`,safe(c.phone||c.email||'—'),safe(c.address||'—'),integer(od.length),money(od.filter(o=>o.status==='Hoàn thành').reduce((z,o)=>z+Number(o.total),0)),money(od.filter(o=>o.status==='Hoàn thành').reduce((z,o)=>z+Math.max(0,o.total-orderPaid(o)),0)),btn('Sửa','edit-customer','compact',`data-id="${safe(c.id)}"`)]);})))}`;}
function monthOptions(){const set=new Set([new Date().toISOString().slice(0,7),...data.expenses.map(e=>String(e.date).slice(0,7)),...data.orders.map(o=>String(o.date).slice(0,7)),...data.purchases.map(p=>String(p.date).slice(0,7)),...data.purchases.flatMap(p=>(p.payments||[]).map(x=>String(x.date).slice(0,7)))].filter(x=>/^\d{4}-\d\d$/.test(x)));return `<select aria-label="Chọn kỳ tài chính" data-filter-month><option value="all" ${ui.month==='all'?'selected':''}>Toàn bộ dữ liệu</option>${[...set].sort().reverse().map(m=>`<option value="${m}" ${ui.month===m?'selected':''}>Tháng ${m.slice(5)}/${m.slice(0,4)}</option>`).join('')}</select>`;}
function pageFinance(){const f=financials(data,ui.month),p=procurementSummary(data,ui.month);return `${head('Tài chính & báo cáo','Lợi nhuận và dòng tiền nhập hàng được theo dõi riêng, không trừ hai lần tiền mua hàng.',`${monthOptions()} ${btn('＋ Ghi chi phí','new-expense','primary')} ${btn('✦ AI phân tích tài chính','finance-ai','primary')} ${btn('Xuất báo cáo CSV','export-report')}`)}<div class="metrics">${card('Doanh thu',money(f.revenue),`${f.orders} đơn hoàn thành`,'↗','green')}${card('Giá vốn xác minh',money(f.cogsKnown),`${f.missing.length} đơn thiếu giá vốn`,'▤')}${card('Chi phí vận hành',money(f.expenses),'Không bao gồm nhập kho','↘','orange')}${card('Lợi nhuận sau chi phí',f.net===null?'Không đủ dữ liệu':money(f.net),f.missing.length?'Chưa thể xác nhận tổng lợi nhuận':'Trước thuế / lãi vay','◉',f.net===null?'orange':'green')}</div>${panel('Dòng tiền khách hàng',`<div class="procurement-summary"><div><small>Thực thu từ khách trong kỳ</small><strong>${money(p.cashReceived)}</strong></div><div><small>Phải thu khách hiện tại</small><strong>${money(customerReceivables(data))}</strong></div><div><small>Còn phải trả dịch vụ</small><strong>${money(p.serviceDebt)}</strong></div></div><p class="caption">Doanh thu ghi theo đơn hoàn thành; thu tiền theo chứng từ đã ghi nhận. Hai chỉ tiêu không bắt buộc bằng nhau.</p>`)}${panel('Tiền mua hàng & công nợ (không trừ trực tiếp vào lợi nhuận)',`<div class="procurement-summary"><div><small>Tiền hàng nhập trong kỳ</small><strong>${money(p.purchaseValue)}</strong></div><div><small>Phí nhập kho đã phân bổ</small><strong>${money(p.landed-p.purchaseValue)}</strong></div><div><small>Đã trả nhà cung cấp trong kỳ</small><strong>${money(p.paidSupplier)}</strong></div><div><small>Phí bên ngoài đã trả khi nhập</small><strong>${money(p.paidExternal)}</strong></div><div><small>Tổng chi tiền nhập hàng trong kỳ</small><strong>${money(p.paidSupplier+p.paidExternal)}</strong></div><div class="outflow-total"><small>TỔNG TIỀN ĐÃ CHI (mua hàng và vận hành)</small><strong>${money(p.paidSupplier+p.paidExternal+f.expenses)}</strong></div><div><small>Công nợ NCC hiện tại</small><strong>${money(p.debtOutstanding)}</strong></div><div><small>Công nợ dịch vụ hiện tại</small><strong>${money(p.serviceDebt)}</strong></div></div><p class="caption">Tiền nhập hàng tự động tăng dòng tiền chi khi thanh toán, nhưng không làm giảm ngay lợi nhuận. Giá trị hàng tồn sẽ đi vào giá vốn khi bán. Phí vận chuyển về kho được phân bổ vào giá vốn, không nhập lại vào chi phí hoạt động. ${btn('Xem phiếu nhập & thanh toán','go-purchase','compact')}</p>`)}${f.missing.length?`<div class="notice-warn"><strong>Thiếu cơ sở tính lợi nhuận:</strong> ${f.missing.length} đơn hoàn thành không có đầy đủ dòng hàng / giá vốn. Doanh thu vẫn được ghi nhận, nhưng không thể tính tổng lợi nhuận chính xác. <small>Đơn: ${f.missing.slice(0,6).map(safe).join(', ')}</small></div>`:''}<div class="columns half">${panel('Công thức tài chính',`<div class="formula"><div><span>Doanh thu hoàn thành</span><strong>${money(f.revenue)}</strong></div><div><span>Giá vốn đã biết</span><strong>− ${money(f.cogsKnown)}</strong></div><div><span>Chi phí hoạt động</span><strong>− ${money(f.expenses)}</strong></div><div class="formula-result"><span>Kết quả kinh doanh</span><strong>${f.net===null?'Chưa xác định':money(f.net)}</strong></div></div><p class="caption">Không bao gồm thuế, chi phí lãi vay và hàng trả lại ngoài quy trình đổi trạng thái.</p>`)}${panel('Cơ cấu chi phí',(()=>{const m={};for(const x of f.expenseRows)m[x.category]=(m[x.category]||0)+x.amount;const max=Math.max(...Object.values(m),1);return Object.entries(m).length?Object.entries(m).sort((a,b)=>b[1]-a[1]).map(([cat,value])=>`<div class="expense-bar"><span>${safe(cat)}</span><strong>${money(value)}</strong><div><i style="width:${value/max*100}%"></i></div></div>`).join(''):empty();})())}</div>${panel('Các khoản chi đã ghi nhận',table(['Ngày','Tên khoản chi','Nhóm chi phí','Số tiền','Thao tác'],f.expenseRows.filter(e=>search(e.name+' '+e.category)).map(e=>tableRow([date(e.date),safe(e.name),safe(e.category),money(e.amount),`${btn('Sửa','edit-expense','compact',`data-id="${safe(e.id)}"`)} ${btn('Chứng từ','view-evidence','compact',`data-id="expense:${safe(e.id)}"`)} ${btn('Xóa','delete-expense','compact danger',`data-id="${safe(e.id)}"`)}`]))))}`;}
function pageAnalytics(){const sales=salesByProduct(data).filter(z=>z.units>0);const trend=monthlyRevenue(data,6);const categories={};for(const x of sales){const p=data.products.find(p=>p.id===x.productId);const key=p?.category||'Khác';categories[key]=(categories[key]||0)+x.revenue;}const total=Object.values(categories).reduce((z,x)=>z+x,0);return `${head('Phân tích kinh doanh','Dữ liệu đã ghi nhận — không dùng ước lượng doanh thu theo SKU cho đơn lịch sử thiếu dòng hàng.')}${panel('Xu hướng 6 tháng',table(['Tháng','Doanh thu','Chi phí hoạt động','Tỷ lệ chi phí / doanh thu'],trend.map(x=>tableRow([x.month,money(x.revenue),money(x.expenses),x.revenue?(x.expenses/x.revenue*100).toFixed(1)+'%':'—']))))}<div class="columns half">${panel('Hiệu quả theo sản phẩm',table(['Sản phẩm','Số lượng bán','Doanh thu'],sales.map(x=>tableRow([safe(x.name),integer(x.units),money(x.revenue)]))))}${panel('Đóng góp doanh thu theo danh mục',total?Object.entries(categories).sort((a,b)=>b[1]-a[1]).map(([name,value])=>`<div class="expense-bar"><span>${safe(name)}</span><strong>${(100*value/total).toFixed(1)}%</strong><div><i style="width:${value/total*100}%"></i></div></div>`).join(''):empty('Chưa có đơn hoàn thành với dòng sản phẩm hợp lệ.'))}</div>`;}
function pageForecast(){
 if(!ui.forecastProduct&&data.products.length)ui.forecastProduct=data.products[0].id;
 const p=data.products.find(p=>p.id===ui.forecastProduct);
 const v=p?analyzeDemand(data,p.id,p.stock||0,p.min||0):null;
 return `${head('Dự báo nhu cầu','Phân tích xu hướng từ lịch sử bán hàng; AI giải thích kịch bản, không tự tạo số dự báo.')}
 ${panel('Chọn mặt hàng',`<div class="row-control"><label>SKU cần dự báo</label><select data-forecast-product>${data.products.map(x=>`<option value="${safe(x.id)}" ${ui.forecastProduct===x.id?'selected':''}>${safe(x.name)}</option>`).join('')}</select></div>`)}
 ${v&&v.sampleOrders>=3?`<div class="metrics three">${card('Đã bán 30 ngày gần nhất',integer(v.last30)+' sp',`${v.sampleOrders} đơn có sản phẩm đang xét`,'▤','blue')}${card('Nhu cầu 30 ngày tham khảo',v.sufficient?integer(v.projected)+' sp':'Chưa đủ dữ liệu',v.sufficient?'Bình quân có trọng số theo 3 giai đoạn':'Chưa đủ lịch sử để xác định xu hướng','⌁','purple')}${card('Lượng nhập cần cân nhắc',v.sufficient?integer(v.reorder)+' sp':'—',v.sufficient?'Tính từ tồn kho và ngưỡng an toàn':'Không đề xuất số khi dữ liệu thiếu','▣','orange')}</div>
 ${panel('Xu hướng bán hàng và mức tin cậy',`<div class="forecast-trend">${v.windows.map((x,i)=>`<div class="forecast-period"><span>${['60–90 ngày trước','30–60 ngày trước','30 ngày gần nhất'][i]}</span><div><i style="width:${Math.max(3,x/Math.max(1,...v.windows)*100)}%"></i></div><strong>${integer(x)} sp</strong></div>`).join('')}</div><p><strong>Xu hướng:</strong> ${safe(v.trendLabel)} · <strong>Độ tin cậy:</strong> ${safe(v.confidence)}</p><p class="caption">${safe(v.explanation)}. Dữ liệu đơn hàng không đủ liên tục hoặc có biến động sẽ làm kết quả kém tin cậy. Đây không phải số liệu do Gemini tự dự đoán.</p>${v.sufficient?btn('Lưu phương án dự báo thành quyết định','forecast-to-decision','primary',`data-id="${safe(p.id)}"`):''}`)}
 ${panel('Giải thích và so sánh bằng AI',`<p>Gemini có thể giải thích nguyên nhân tăng/giảm và đề xuất kịch bản nhập hàng. Kết luận phải dựa trên số liệu và ghi rõ những giả định.</p><button type="button" class="btn primary" data-chat-prompt="Phân tích nhu cầu sản phẩm ${safe(p.name)} theo lịch sử bán hàng của doanh nghiệp. So sánh các kịch bản nhu cầu tăng hoặc giảm, giải thích độ tin cậy và lượng nhập phù hợp; tuyệt đối không bịa dữ liệu.">✧ Yêu cầu Gemini phân tích dự báo</button>`)}
 `:`${panel('Dữ liệu chưa đủ để dự báo đáng tin cậy',`<div class="notice-warn">${v?safe(v.explanation):'Chưa có mặt hàng để phân tích.'} Hệ thống không dùng số bán kỳ trước làm dự báo chắc chắn.</div><p class="caption">Hãy tích lũy lịch sử giao dịch qua nhiều kỳ; ưu tiên thêm các đơn có ngày bán và SKU đầy đủ.</p>`)}`}`;
}

function sensitivityPanel(){
 const base=scenario(data,{pricePct:0,unitsPct:0,costPct:0,expensesPct:0},ui.month);
 if(!base)return panel('Kiểm tra độ nhạy',empty('Chưa có đủ giá vốn xác minh để phân tích độ nhạy.'));
 const risks=[['Giá bán giảm 10%',{pricePct:-10}],['Lượng bán giảm 20%',{unitsPct:-20}],['Giá vốn tăng 10%',{costPct:10}],['Chi phí hoạt động tăng 15%',{expensesPct:15}]];
 const rows=risks.map(([title,change])=>{
   const r=scenario(data,{pricePct:0,unitsPct:0,costPct:0,expensesPct:0,...change},ui.month);
   return tableRow([safe(title),r?money(r.net):'Không đủ dữ liệu',r?`<strong class="${r.net<base.net?'negative':'positive'}">${r.change>=0?'+':''}${money(r.change)}</strong>`:'—']);
 });
 return panel('Phân tích độ nhạy · phương án bất lợi',`${table(['Biến động giả định','Lợi nhuận sau biến động','Chênh lệch so với hiện tại'],rows)}<p class="caption">Thay đổi từng yếu tố riêng lẻ, các yếu tố khác giữ nguyên. Đây là mô phỏng điều kiện, không phải dự báo chắc chắn.</p>`);
}

function pageScenarios(){const sc=scenario(data,ui.scenario,ui.month),goal=goalSeek(data,ui.goal,ui.month),f=financials(data,ui.month);return `${head('Mô phỏng & mục tiêu lợi nhuận','Điều chỉnh giả định và so sánh kết quả; mô hình chỉ chạy khi biết đầy đủ giá vốn.')}${panel('Thay đổi các giả định',`<form id="scenario-form" class="scenario-grid"><label>Giá bán thay đổi (%)<input name="pricePct" type="number" step="1" min="-80" max="100" value="${ui.scenario.pricePct}" /></label><label>Số lượng bán thay đổi (%)<input name="unitsPct" type="number" step="1" min="-100" max="200" value="${ui.scenario.unitsPct}" /></label><label>Giá vốn / đơn vị (%)<input name="costPct" type="number" step="1" min="-80" max="200" value="${ui.scenario.costPct}" /></label><label>Chi phí vận hành (%)<input name="expensesPct" type="number" step="1" min="-100" max="200" value="${ui.scenario.expensesPct}" /></label><button type="submit" class="btn primary">Tính lại phương án</button></form>`)}${sc?`<div class="metrics three">${card('Lợi nhuận cơ sở',money(sc.baseNet),'Từ giao dịch hoàn thành','◉')}${card('Lợi nhuận phương án',money(sc.net),'Theo giả định đã chọn','◇','purple')}${card('Chênh lệch',`${sc.change>=0?'+':''}${money(sc.change)}`,'Không phải dự báo doanh thu chắc chắn','↗',sc.change>=0?'green':'orange')}</div>`:`<div class="notice-warn">Không thể mô phỏng lợi nhuận vì còn ${f.missing.length} đơn thiếu giá vốn. Cần bổ sung dữ liệu hợp lệ, không tự đoán số liệu.</div>`}${sc?`<div class="decision-prompt"><strong>Đưa phương án vào quy trình phê duyệt</strong><p>Lưu giả định và kết quả mô phỏng để so sánh với thực tế sau khi thực hiện.</p>${btn('Lưu mô phỏng thành quyết định','scenario-to-decision','primary')}</div>`:''}${sensitivityPanel()}${panel('Tìm doanh thu mục tiêu (Goal-seeking)',`<form id="goal-form" class="row-control"><label>Mục tiêu lợi nhuận trước thuế (₫)<input type="text" data-money inputmode="numeric" pattern="[0-9.]*" autocomplete="off" name="goal" value="${formatVndInput(ui.goal)}"></label><button class="btn primary" type="submit">Tính doanh thu cần đạt</button></form>${goal?`<div class="result-box"><div><span>Doanh thu tối thiểu cần đạt</span><strong>${money(goal.requiredRevenue)}</strong></div><div><span>Doanh thu cần tăng thêm so với hiện tại</span><strong>${money(goal.moreRevenue)}</strong></div><p class="caption">Biên đóng góp: ${(goal.margin*100).toFixed(1)}%. ${goal.assumption}</p></div>`:`<p class="caption">Chưa đủ dữ liệu xác thực hoặc biên đóng góp không dương để giải bài toán.</p>`}`)}`;}
function pageRanking(){let rank=[];try{rank=scoreSuppliers(data)}catch{}const productId=ui.compareProduct||data.products[0]?.id||'';let offers=[];try{if(productId)offers=compareSupplierOffers(data,productId,ui.compareQty)}catch{}const comparePanel=panel('So sánh giá thực tế trước khi đặt mua',`<form id="compare-supplier-form" class="row-control">${select('productId','Sản phẩm',pOpts(true),productId)}${input('quantity','Số lượng dự kiến',ui.compareQty,'number',true,'min="1" step="1"')}<button class="btn primary" type="submit">So sánh</button></form><p class="caption">Chỉ hiển thị đối tác có giá nhập từng được ghi nhận với sản phẩm này. Giá là tham khảo từ phiếu mua cũ, không phải báo giá hiện tại.</p>${table(['Nhà cung cấp','Giá mua gần nhất','Tiền hàng','Phí giao dự tính','Tổng dự tính','Đúng hẹn','Chọn đối tác'],offers.map(o=>tableRow([safe(o.supplier),`${money(o.unitPrice)}<small>${date(o.priceDate)}</small>`,money(o.merchandise),o.unknown?'Cần hỏi báo giá':money(o.freight),o.unknown?'Chưa xác định':`<strong>${money(o.estimatedTotal)}</strong>`,o.sample?`${o.onTimePct}% · ${o.sample} phiếu`:'Chưa đủ dữ liệu',btn('Tạo phiếu mua','buy-from-supplier','compact',`data-id="${safe(o.supplierId)}"`) ])))}${offers.length?'<p class="caption">Ước tính không gồm chi phí bốc xếp chưa biết. Hãy xác nhận phí và chất lượng trước khi chọn.</p>':''}`);return `${head('Đánh giá nhà cung cấp','So sánh chính sách và kết quả giao hàng có ghi nhận; phần chấm điểm 1–5 là đánh giá của người quản lý.')}${comparePanel}${panel('Trọng số đánh giá',`<form id="weights-form" class="row-control"><label>Giá (%)<input type="number" name="price" min="0" max="100" step="1" value="${data.weights.price}"></label><label>Giao hàng (%)<input type="number" name="delivery" min="0" max="100" step="1" value="${data.weights.delivery}"></label><label>Chất lượng (%)<input type="number" name="quality" min="0" max="100" step="1" value="${data.weights.quality}"></label><button type="submit" class="btn primary">Cập nhật trọng số</button></form><p class="caption">Trọng số được chuẩn hóa theo tổng, không bắt buộc tổng bằng 100. Chỉ nhà cung cấp đã được bạn chấm điểm mới xuất hiện trong xếp hạng. Điểm giao hàng tự tính khi có ít nhất 3 phiếu đã nhận ghi đủ ngày hẹn và ngày giao; nếu ít hơn, dùng điểm đánh giá do quản lý nhập. Giá và chất lượng vẫn cần đối chiếu báo giá, biên bản thực tế.</p>`)}${panel('Dữ liệu giao hàng thực tế',table(['Nhà cung cấp','Chính sách vận chuyển','Phiếu đã nhận có hẹn','Đúng hẹn','Giao đủ','Tổng giá trị đã nhập'],data.suppliers.filter(s=>s.type!=='Vận chuyển'&&s.type!=='Dịch vụ').map(s=>{const st=supplierDeliveryStats(data,s.id);const purchases=data.purchases.filter(p=>p.supplierId===s.id&&delivered(p));return tableRow([safe(s.name),safe(supplierPolicies(s)),`${st.sample} phiếu`,st.sample?`${st.onTimePct}%`:'Chưa đủ dữ liệu',st.sample?`${st.fillPct}% (lỗi ${st.defectPct}%)`:'Chưa đủ dữ liệu',money(purchases.reduce((z,p)=>z+Number(p.landedTotal||0),0))]);}))) }${panel('Ma trận đánh giá và xếp hạng',table(['Xếp hạng','Nhà cung cấp','Giá','Giao hàng','Chất lượng','Điểm tổng hợp','Thao tác'],rank.map((s,i)=>tableRow([`<strong>#${i+1}</strong>`,safe(s.name),integer(s.ratings.price)+'/5',`${integer(s.deliveryUsed)}/5${s.deliveryMeasured?' (tự tính)':''}`,integer(s.ratings.quality)+'/5',`<strong>${s.score.toFixed(2)}/5</strong>`,`${btn('Chấm điểm','rate-supplier','compact',`data-id="${safe(s.id)}"`)} ${btn('Nhập hàng','buy-from-supplier','compact',`data-id="${safe(s.id)}"`)}`]))))}${data.suppliers.some(x=>!data.ratings[x.id])?panel('Chưa chấm điểm',data.suppliers.filter(x=>!data.ratings[x.id]).map(x=>`<div class="unrated-row"><strong>${safe(x.name)}</strong>${btn('Chấm điểm','rate-supplier','compact',`data-id="${safe(x.id)}"`)}</div>`).join('')):''}${rank.length?`<div class="decision-prompt"><strong>Phương án dẫn đầu: ${safe(rank[0].name)}</strong><p>Điểm tổng hợp ${rank[0].score.toFixed(2)}/5 theo trọng số và điểm đã nhập. Điểm số là đánh giá chủ quan, cần kiểm chứng bằng dữ liệu thực.</p>${btn('Lưu đề xuất thành quyết định','rank-to-decision','primary')}</div>`:''}`;}
function pageAlerts(){const r=simpleRecommendation(data);const list=[...r.lateDeliveries.map(p=>({severity:'high',title:`Trễ hẹn giao hàng: ${supplierName(p.supplierId)}`,desc:`Phiếu ${p.id} dự kiến ${date(p.expectedDelivery)} nhưng chưa xác nhận đã nhận.`,act:'go-purchase'})),...r.low.map(p=>({severity:'high',title:`Tồn kho thấp: ${p.name}`,desc:`Còn ${p.stock}, ngưỡng ${p.min}; cần bổ sung tối thiểu ${Math.max(0,p.min-p.stock)} đơn vị tới ngưỡng.`,act:'suggest-replenishment',id:p.id})),...r.debts.map(p=>({severity:'medium',title:`Công nợ: ${p.name}`,desc:`Còn ${money(p.debt)} từ phiếu mua chưa thanh toán.`,act:'go-payment'})),...(r.unverified?[{severity:'high',title:'Thiếu dữ liệu giá vốn',desc:`Có ${r.unverified} đơn hoàn thành chưa đủ chi tiết để kết luận tổng lợi nhuận.`,act:'go-finance'}]:[])];return `${head('Cảnh báo kinh doanh','Cảnh báo từ các điều kiện có thể kiểm chứng; không giả định đây là thông báo AI.')}${panel('Danh sách cảnh báo theo mức độ',list.length?`<div class="alert-list">${list.map(x=>`<div class="alert-item ${x.severity}"><span>⚑</span><div><strong>${safe(x.title)}</strong><p>${safe(x.desc)}</p></div>${btn('Xử lý →',x.act,'compact',x.id?`data-id="${safe(x.id)}"`:'')}</div>`).join('')}</div>`:empty('Không có cảnh báo với dữ liệu và ngưỡng hiện tại.'))}`;}
function pageDecisions(){return `${head('Vòng đời quyết định','Ghi nhận vấn đề → phương án → phê duyệt → thực hiện → so sánh mục tiêu và kết quả.',btn('＋ Tạo quyết định','new-decision','primary'))}${panel('Hồ sơ quyết định',table(['Quyết định','Căn cứ / kết quả kỳ vọng','Người phụ trách','Hạn','Trạng thái','Thao tác'],data.decisions.filter(d=>search(d.title+' '+d.reason)).map(d=>tableRow([`<strong>${safe(d.title)}</strong><small>${safe(d.id)}</small>`,`<span class="small-text">${safe(d.reason)}</span><small>Kỳ vọng: ${safe(d.expected||'Chưa xác định')}<br>Thực tế: ${safe(d.actual||'Chưa đánh giá')}</small>`,safe(d.owner),date(d.due),badge(d.status),btn('Cập nhật','edit-decision','compact',`data-id="${safe(d.id)}"`)]))))}`;}

function pageSettings(){return `${head('Hồ sơ và cấu hình doanh nghiệp','Đổi tên doanh nghiệp sẽ cập nhật tên trên menu và báo cáo, đồng thời được lưu vào dữ liệu.')}${panel('Thông tin doanh nghiệp',`<form id="settings-form" class="form-grid"><label>Tên doanh nghiệp / cửa hàng<input name="name" required maxlength="120" value="${safe(data.company.name)}"></label><label>Ngành nghề<input name="sector" maxlength="100" value="${safe(data.company.sector||'')}"></label><label>Số điện thoại<input name="phone" maxlength="40" value="${safe(data.company.phone||'')}"></label><label>Email<input name="email" type="email" maxlength="120" value="${safe(data.company.email||'')}"></label><label class="wide">Địa chỉ<input name="address" maxlength="240" value="${safe(data.company.address||'')}"></label><div class="wide"><button type="submit" class="btn primary">Lưu thông tin doanh nghiệp</button></div></form>`)}${panel('Giao diện cá nhân hóa',`<div class="config-grid"><div><h3>Màu chủ đạo</h3><div class="theme-choices">${[['blue','#2563eb'],['indigo','#5956d6'],['emerald','#059669'],['teal','#0891b2'],['coral','#ef6a58'],['navy','#122b50']].map(([id,c])=>`<button type="button" class="theme-dot ${prefs.theme===id?'current':''}" data-preference="theme" data-value="${id}" style="background:${c}" aria-label="Màu ${id}" title="Màu ${id}"></button>`).join('')}</div></div><label>Cỡ chữ<select data-preference="font"><option value="small" ${prefs.font==='small'?'selected':''}>Nhỏ</option><option value="medium" ${prefs.font==='medium'?'selected':''}>Vừa</option><option value="large" ${prefs.font==='large'?'selected':''}>Lớn</option></select></label><label>Ngôn ngữ / Language<select data-preference="lang"><option value="vi" ${prefs.lang==='vi'?'selected':''}>Tiếng Việt</option><option value="en" ${prefs.lang==='en'?'selected':''}>English</option></select></label><label class="wide">Logo doanh nghiệp (ảnh JPG/PNG/WebP)<input type="file" id="company-logo-file" accept="image/jpeg,image/png,image/webp"></label>${data.company.logo?`<div class="wide settings-actions"><button type="button" class="btn danger" data-action="remove-company-logo">Xóa logo đã tải</button></div>`:""}<p class="caption wide">Tùy chỉnh giao diện được ghi nhớ trên thiết bị; logo doanh nghiệp được đồng bộ với dữ liệu doanh nghiệp.</p></div>`)}${panel('Thành viên & bảo mật',`<p class="muted">Tài khoản đang dùng: <strong>${safe(cloud.user?.email||'Chế độ xem thử')}</strong> · Vai trò: <strong>${safe(cloud.org?.role||'Xem thử')}</strong></p><div class="settings-actions">${btn('Tạo mã mời 7 ngày','create-invite','primary')}${btn('Chuyển doanh nghiệp','switch-org')}${btn('Đổi mật khẩu','change-password')}${btn('Đăng xuất','logout')}</div><div id="invite-output" class="caption"></div>`)}${panel('Dữ liệu & sao lưu',`<p class="muted">Bản v7 lưu dữ liệu làm việc của mỗi doanh nghiệp trên Supabase sau khi đăng nhập, với quyền thành viên tách biệt. Chứng từ tải lên lưu trong vùng Storage riêng. Chế độ xem thử vẫn sử dụng trình duyệt và không chia sẻ. Hãy xuất bản sao lưu trước khi xóa dữ liệu trình duyệt. Trong chế độ đăng nhập, chứng từ mới được lưu ở Storage riêng của doanh nghiệp; bản demo có thể dùng lưu trữ cục bộ. Không tải lên chứng từ nếu chưa xác nhận người nhận đúng.</p><div class="settings-actions">${btn('↓ Xuất bản sao lưu JSON','backup','primary')}${btn('↑ Nhập sao lưu v3 / bản cũ','restore')}${btn('↗ Chuyển dữ liệu từ phiên bản cũ','migrate')}${btn('Khởi tạo dữ liệu mẫu','reset-demo')}${btn('Bắt đầu dữ liệu trống','reset-empty','danger')}</div><input type="file" id="restore-file" accept="application/json,.json" hidden><p class="caption">Dữ liệu demo cũ được giữ riêng và không tự chuyển vào doanh nghiệp mới. Có thể khôi phục từ bản sao lưu trong cùng trình duyệt / tên miền, hoặc tải lên tệp sao lưu smartdecision-local-v1 cũ. Các giao dịch lịch sử thiếu giá vốn sẽ tiếp tục được ghi nhãn chưa xác minh.</p>`)}}`;}
function head(label,subtitle,action=''){return `<div class="section-intro"><div><h2>${label}</h2><p>${subtitle}</p></div><div class="actions">${action}</div></div>`;}
function search(t){return String(t||'').toLowerCase().includes(ui.filter.toLowerCase());}
const pages={dashboard:main,orders:pageOrders,products:pageProducts,inventory:pageInventory,suppliers:pageSuppliers,customers:pageCustomers,finance:pageFinance,analytics:pageAnalytics,forecast:pageForecast,scenarios:pageScenarios,ranking:pageRanking,alerts:pageAlerts,decisions:pageDecisions,settings:pageSettings};
function render(){applyPreferences();if(!['app','preview'].includes(runtime.mode)){renderAccount();return;}const previousScroll=typeof window.scrollY==='number'?window.scrollY:0;const sidebarScroll=document.querySelector('.sidebar')?.scrollTop??0;document.title=`${titles[ui.page]} · RetailMind`;const root=document.getElementById('app');root.innerHTML=`<div class="shell"><aside class="sidebar ${ui.sidebar?'mobile-open':''}"><div class="brand"><div class="brand-mark" aria-hidden="true">${data.company.logo?`<img src="${safe(data.company.logo)}" alt="Logo doanh nghiệp" class="company-logo">`:`<svg viewBox="0 0 48 48" width="37" height="37" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M10 35L21 24L29 30L40 13" stroke="#FAFBFF" stroke-width="3.6" stroke-linecap="round" stroke-linejoin="round"/><circle cx="10" cy="35" r="4" fill="#8FE6D3"/><circle cx="21" cy="24" r="4" fill="#E7E9FF"/><circle cx="29" cy="30" r="4" fill="#A7B1FF"/><circle cx="40" cy="13" r="4" fill="#8FE6D3"/></svg>`}</div><div><strong>RetailMind</strong><small>DỮ LIỆU · PHÂN TÍCH · QUYẾT ĐỊNH</small></div></div><div class="org-chip"><div class="org-icon">${data.company.logo?`<img class="org-logo-image" src="${safe(data.company.logo)}" alt="Logo doanh nghiệp">`:`<svg viewBox="0 0 40 40" width="27" height="27" aria-hidden="true"><rect x="4" y="23" width="7" height="13" rx="2" fill="currentColor" opacity=".6"/><rect x="16" y="15" width="7" height="21" rx="2" fill="currentColor" opacity=".8"/><rect x="28" y="6" width="7" height="30" rx="2" fill="currentColor"/></svg>`}</div><div><span>DOANH NGHIỆP</span><strong title="${company()}">${company()}</strong></div></div><nav>${nav.map(g=>`<div class="nav-group"><div class="nav-label">${g.group}</div>${g.items.map(([id,icon,label])=>`<button style="--navaccent:${navColors[id]||'#9cc1ed'}" class="nav-item ${ui.page===id?'selected':''}" data-go="${id}"><span class="nav-icon">${icon}</span><span>${label}</span>${ui.page===id?'<i></i>':''}</button>`).join('')}</div>`).join('')}</nav><div class="sidebar-bottom"><span class="dot"></span>Hỗ trợ quyết định <small>Phiên bản 8 · ${runtime.preview?'Xem thử':'Dữ liệu doanh nghiệp'}</small></div></aside><div class="sidebar-shade ${ui.sidebar?'visible':''}" data-action="close-nav"></div><div class="workspace"><header class="topbar"><div class="top-left"><button class="mobile-toggle" data-action="toggle-nav" aria-label="Mở menu">☰</button><div class="breadcrumb">Không gian quản trị <span>›</span> <strong>${safe(titles[ui.page])}</strong></div></div><div class="top-right"><span class="scope" id="sync-status">${runtime.preview?'● XEM THỬ (CỤC BỘ)':runtime.saving?'● Đang đồng bộ':'● Đã đồng bộ'}</span><button type="button" class="top-settings" data-go="settings" title="Cài đặt">⚙</button><button type="button" class="top-settings" data-auth-action="logout" title="Đăng xuất">⇥</button></div></header><main class="content"><div class="page-hero ${ui.page==='dashboard'?'hero-dashboard-hidden':''}"><div class="hero-copy"><div class="eyebrow">RETAILMIND / ${safe(titles[ui.page].toUpperCase())}</div><h1>${safe(titles[ui.page])}</h1><p>${ui.page==='dashboard'?'Phát hiện vấn đề, xem số liệu mới và chuyển thẳng tới nơi xử lý.':{orders:'Đơn bán, số tiền khách đã trả và các khoản còn phải thu.',products:'Mỗi SKU có một giá bán và một giá vốn cập nhật từ nhập kho.',inventory:'Theo dõi lượng tồn, biến động và đối chiếu kiểm kê.',suppliers:'Từ đơn mua đến giao hàng, kiểm nhận và thanh toán từng lần.',customers:'Hồ sơ người mua, địa chỉ giao và lịch sử đơn hàng.',finance:'Tách tiền đã chi với giá vốn của hàng đã bán.',analytics:'Nhìn xu hướng kinh doanh từ những giao dịch đã ghi nhận.',forecast:'Ước lượng nhu cầu có căn cứ khi lịch sử đủ dữ liệu.',scenarios:'Thử thay đổi giá, lượng bán và chi phí trước khi quyết định.',ranking:'Đánh giá đối tác theo chi phí và lịch sử giao nhận.',decisions:'Theo dõi mục tiêu, phương án và kết quả sau thực hiện.',settings:'Tùy chỉnh thông tin và xuất bản sao lưu dữ liệu.',alerts:'Những vấn đề cần xử lý dựa trên số liệu hiện có.'}[ui.page]||''}</p></div><div class="hero-shape">✧</div></div>${ui.page!=='settings'?`<div class="content-toolbar"><div class="data-label"><span class="dot"></span> ${runtime.mode==='app'?'Dữ liệu doanh nghiệp đang đồng bộ':data.demo?'Đang xem dữ liệu minh họa':'Dữ liệu xem thử trên thiết bị'} <small>· ${data.orders.length} đơn · ${data.products.length} sản phẩm</small></div>${['orders','products','suppliers','customers','inventory','decisions','finance'].includes(ui.page)?`<label class="search"><span>⌕</span><input id="page-search" value="${safe(ui.filter)}" placeholder="Tìm nhanh..." autocomplete="off" /></label>`:''}</div>`:''}<div class="page-content">${(pages[ui.page]||main)()}</div><footer>RetailMind © 2026 · Quản trị và hỗ trợ quyết định</footer></main></div><button class="chat-fab ${ui.chatOpen?'active':''}" style="${ui.chatFabPos?`left:${Math.max(0,Math.min(innerWidth-200,ui.chatFabPos.x))}px;top:${Math.max(0,Math.min(innerHeight-65,ui.chatFabPos.y))}px;right:auto;bottom:auto;`:``}" data-action="toggle-chat" aria-label="Mở trợ lý phân tích"><span>✦</span><span>Trợ lý phân tích</span></button><div id="chat-slot">${chatHtml()}</div><div id="modal-slot"></div><div id="toast" class="toast" role="status" aria-live="polite"></div></div>`;const sidebarAfterRender=document.querySelector('.sidebar');if(sidebarAfterRender)sidebarAfterRender.scrollTop=sidebarScroll;if(typeof window.scrollTo==='function'&&previousScroll>0)window.scrollTo(0,previousScroll);translateUI(root,prefs.lang);}
function humanizeAi(text){
 let v=String(text||'').replace(/\\text\{([^{}]*)\}/g,'$1').replace(/\\times/g,' × ').replace(/\\cdot/g,' · ')
  .replace(/\\frac\{([^{}]+)\}\{([^{}]+)\}/g,'($1 / $2)')
  .replace(/\\\[|\\\]|\\\(|\\\)/g,'').replace(/\$\$/g,'').replace(/\\%/g,'%');
 return v.replace(/\\left|\\right/g,'').replace(/\\approx/g,'≈').replace(/\\leq/g,'≤').replace(/\\geq/g,'≥');
}
function renderAiMessage(text){
 const v=humanizeAi(text);
 return v.split(/\r?\n/).map(line=>{
  let t=safe(line).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`\n]+)`/g,'<code>$1</code>');
  const h=t.match(/^\s*#{1,4}\s+(.+)$/);if(h)return `<div class="ai-heading">${h[1]}</div>`;
  if(/^\s*(?:[-*•]|\d+[.)])\s+/.test(t))return `<div class="ai-item">${t.replace(/^\s*(?:[-*•]|\d+[.)])\s+/,'')} </div>`;
  return t?`<div class="ai-line">${t}</div>`:'<div class="ai-spacer"></div>';
 }).join('');
}
function chatHtml(){if(!ui.chatOpen)return '';const pos=ui.chatPos?`left:${Math.max(0,Math.min(innerWidth-310,ui.chatPos.x))}px;top:${Math.max(0,Math.min(innerHeight-240,ui.chatPos.y))}px;right:auto;bottom:auto;`:'';return `<div class="chat-panel" style="${pos}"><div class="chat-head" id="chat-handle"><span class="chat-logo">✦</span><div><strong>Trợ lý RetailMind</strong><small>⠿ Giữ và kéo thanh này để di chuyển</small></div><button type="button" data-action="reset-chat-position" class="icon-button" aria-label="Đặt lại vị trí" title="Đặt lại vị trí">⤢</button><button type="button" data-action="toggle-chat" class="icon-button" aria-label="Đóng">✕</button></div><div class="chat-body" id="chat-body">${ui.chat.map(x=>`<div class="bubble ${x.role==='user'?'user':'assistant'}">${x.role==='user'?safe(x.text):renderAiMessage(x.text)}</div>`).join('')}${ui.chatBusy?'<div class="bubble assistant">Đang phân tích yêu cầu…</div>':''}</div><div class="chat-actionbar"><button type="button" data-action="chat-to-decision" class="chat-save-decision" title="Chỉ lưu đề xuất sau khi bạn xác nhận">＋ Lưu phân tích thành đề xuất</button></div><div class="prompt-chips"><button data-chat-prompt="Phân tích doanh thu và giới hạn của dữ liệu">Doanh thu</button><button data-chat-prompt="Các sản phẩm cần nhập kho ưu tiên">Cảnh báo kho</button><button data-chat-prompt="Gợi ý phương án cải thiện lợi nhuận">Quyết định</button></div><form id="chat-form" class="chat-form"><input name="question" placeholder="Hỏi về hoạt động kinh doanh..." value="${safe(ui.chatInput)}" ${ui.chatBusy?'disabled':''} required><button type="button" class="chat-mic" data-action="mic" aria-label="Nhập bằng giọng nói" title="Nói bằng giọng nói"><svg viewBox="0 0 24 24" aria-hidden="true" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10a7 7 0 0 0 14 0M12 17v5m-4 0h8"/></svg></button><button type="submit" ${ui.chatBusy?'disabled':''} aria-label="Gửi">➜</button></form></div>`;}
function modal(title,inner,id){document.getElementById('modal-slot').innerHTML=`<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-label="${safe(title)}"><div class="modal-title"><h2>${safe(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Đóng">✕</button></div><form id="${id}" class="modal-form">${inner}<div class="modal-actions"><button type="button" data-action="close-modal" class="btn secondary">Hủy</button><button type="submit" class="btn primary">Lưu thông tin</button></div></form></section></div>`;}
const input=(name,label,value='',type='text',required=true,extra='')=>{
 const isMoney=type==='number' && /(?:₫|giá bán|đơn giá mua|giá trị đơn|phí vận chuyển|phí bốc xếp|đã trả phí|đã thanh toán)/i.test(label) && !/(?:%|1[–-]5)/.test(label);
 return `<label>${safe(label)}<input name="${name}" type="${isMoney?'text':type}" ${isMoney?'data-money inputmode="numeric" pattern="[0-9.]*" autocomplete="off"':''} value="${safe(isMoney?formatVndInput(value):value)}" ${required?'required':''} ${isMoney?'':extra} /></label>`;
};
const select=(name,label,options,value='',required=true)=>`<label>${safe(label)}<select name="${name}" ${required?'required':''}>${options.map(([k,t])=>`<option value="${safe(k)}" ${value===k?'selected':''}>${safe(t)}</option>`).join('')}</select></label>`;
const categories=()=>[...new Set(data.products.map(p=>String(p.category||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'vi'));
function categoryControl(p){const current=p?.category||'',options=categories();const selected=current&&!options.includes(current)?'__new__':current||options[0]||'__new__';
 const entries=[...options.map(z=>[z,z]),['__new__','＋ Thêm danh mục mới']];
 return `<div class="category-control">${select('categoryChoice','Danh mục sản phẩm',entries,selected)}<label class="category-new" ${selected==='__new__'?'':'hidden'}>Tên danh mục mới<input name="newCategory" placeholder="Ví dụ: Văn phòng phẩm" maxlength="80" value="${selected==='__new__'?safe(current):''}" ${selected==='__new__'?'required':''}></label></div>`;
}
const pOpts=(blank=false)=>[...(blank?[['','Chọn sản phẩm']]:[]),...data.products.map(p=>[p.id,`${p.name} (còn ${p.stock})`])];
const supOpts=(blank=false)=>[...(blank?[['','Chọn nhà cung cấp']]:[]),...data.suppliers.filter(s=>!['Vận chuyển','Dịch vụ'].includes(s.type)).map(s=>[s.id,s.name])];
const serviceOpts=()=>[['','Chọn đối tác nhận phí'],...data.suppliers.map(s=>[s.id,`${s.name}${s.type==='Hàng hóa'?'':' · '+s.type}`]),['__new__','＋ Thêm đối tác mới ngay tại đây']];
const expenseCategories=()=>[...new Set(['Vận hành','Marketing','Logistics','Nhân sự','Điện nước',...data.expenses.map(e=>String(e.category||'').trim())].filter(Boolean))].sort((a,b)=>a.localeCompare(b,'vi'));
function expenseCategoryControl(e){const category=e?.category||'Vận hành';const options=expenseCategories();return `<div class="expense-category-control">${select('expenseCategoryChoice','Nhóm chi phí',[...options.map(x=>[x,x]),['__new__','＋ Thêm nhóm chi phí mới']],category)}<label class="expense-category-new" hidden>Tên nhóm mới<input name="newExpenseCategory" maxlength="70" placeholder="Ví dụ: Bảo trì" /></label></div>`;}
const customersOpts=()=>[['','Chọn khách hàng'],...data.customers.map(c=>[c.id,`${c.name}${c.phone?' · '+c.phone:''}`])];
function orderLine(){return `<div class="order-line">${select('productId','Sản phẩm',pOpts(true))}${input('quantity','Số lượng','1','number',true,'min="1" step="1"')}<button type="button" data-action="remove-line" class="icon-button line-remove" aria-label="Xóa dòng">✕</button></div>`;}
// Supporting receipts are stored as original browser-local files in IndexedDB, not in localStorage.
// No upload to third-party servers. Evidence is NOT proof of payment by itself.
function evidenceDatabase(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window))return reject(Error('Trình duyệt không hỗ trợ lưu chứng từ.'));const r=indexedDB.open('smartdecision_evidence_v1',1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('attachments'))r.result.createObjectStore('attachments',{keyPath:'ref'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function storeEvidence(ref,file){if(!file||!file.size)return;const mime=file.type;
 if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(mime))throw Error('Chỉ hỗ trợ ảnh JPG, PNG, WebP hoặc PDF.');
 if(file.size>6*1024*1024)throw Error('Chứng từ tối đa 6 MB.');
 const db=await evidenceDatabase();try{await new Promise((resolve,reject)=>{const tx=db.transaction('attachments','readwrite');tx.objectStore('attachments').put({ref,name:file.name,mime,blob:file,date:new Date().toISOString()});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}finally{db.close();}}
async function readEvidence(ref){const db=await evidenceDatabase();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('attachments','readonly');const q=tx.objectStore('attachments').get(ref);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}finally{db.close();}}
async function showEvidence(ref){try{const remote=runtime.mode==='app'?data.evidenceIndex?.[ref]:null;if(remote){const u=await cloud.fileUrl(remote.path);const inner=remote.mime==='application/pdf'?`<iframe src="${safe(u)}" title="Chứng từ PDF" class="evidence-frame"></iframe>`:`<img src="${safe(u)}" alt="Ảnh chứng từ" class="evidence-image">`;document.getElementById('modal-slot').innerHTML=`<div class="modal-backdrop" data-action="close-modal"><section class="modal evidence-modal"><div class="modal-title"><h2>${safe(remote.name)}</h2><button class="icon-button" data-action="close-modal">✕</button></div><div class="evidence-content">${inner}<p>Chứng từ do người dùng cung cấp, chưa được ngân hàng xác minh.</p></div></section></div>`;return;}const record=await readEvidence(ref);if(!record)return notice('Chưa có chứng từ đính kèm cho giao dịch này.','bad');const u=URL.createObjectURL(record.blob);const inner=record.mime==='application/pdf'?`<iframe src="${u}" title="Chứng từ PDF" class="evidence-frame"></iframe>`:`<img src="${u}" alt="Ảnh chứng từ đã tải lên" class="evidence-image">`;
 document.getElementById('modal-slot').innerHTML=`<div class="modal-backdrop" data-action="close-modal"><section class="modal evidence-modal" role="dialog" aria-modal="true"><div class="modal-title"><h2>${safe(record.name)}</h2><button class="icon-button" data-action="close-modal" aria-label="Đóng">✕</button></div><div class="evidence-content">${inner}<p>Chứng từ do người dùng cung cấp, hệ thống chưa xác minh tính hợp lệ.</p><a href="${u}" download="${safe(record.name)}" class="btn primary">↓ Tải chứng từ</a></div></section></div>`;
 }catch(err){notice(err.message||'Không thể mở chứng từ.','bad');}}
function evidenceField(label='Đính kèm chứng từ (không bắt buộc)',name='evidence'){return `<label>${safe(label)}<input name="${safe(name)}" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" /><small class="field-help">Ảnh JPG, PNG, WebP hoặc PDF đến 6 MB. Lưu riêng cho doanh nghiệp đang đăng nhập; không gửi cho AI.</small></label>`;}
async function exportEvidence(){let db;try{db=await evidenceDatabase();return await new Promise((resolve,reject)=>{const tx=db.transaction('attachments','readonly'),request=tx.objectStore('attachments').getAll();request.onsuccess=async()=>{try{const result=[];for(const record of request.result){if(!record.blob||!record.mime)continue;const b64=await new Promise((yes,no)=>{const fr=new FileReader();fr.onload=()=>yes(fr.result);fr.onerror=()=>no(fr.error);fr.readAsDataURL(record.blob);});result.push({ref:record.ref,name:record.name,mime:record.mime,dataUrl:b64,date:record.date});}resolve(result);}catch(e){reject(e);}};request.onerror=()=>reject(request.error);});}catch(err){console.warn('Chứng từ không thể xuất',err);return [];}finally{db?.close();}}
async function backupAll(){try{const evidence=await exportEvidence();const pack={schema:'smartdecision-v3',exportedAt:new Date().toISOString(),data,evidence};const text=JSON.stringify(pack,null,2);if(text.length>65*1024*1024)return notice('Bản sao lưu quá lớn (trên 65 MB). Hãy giảm số chứng từ hoặc lưu chứng từ ra từng tệp.','bad');download('retailmind-sao-luu-day-du.json',text,'application/json');}catch(err){notice('Không xuất được bản sao lưu: '+err.message,'bad');}}
async function restoreEvidence(records){if(!Array.isArray(records))return 0;if(records.length>500)throw Error('Bản sao lưu có quá nhiều chứng từ.');let count=0;for(const rec of records){if(!rec||typeof rec.ref!=='string'||!/^(purchase|payment|receipt|orderpay|refund|expense|audit):[\w-]{1,90}$/.test(rec.ref)||typeof rec.dataUrl!=='string')continue;if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(rec.mime))continue;const b64=rec.dataUrl.split(',')[1]||'';if(b64.length>9*1024*1024)continue;const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));const file=new File([bytes],String(rec.name||'Chứng từ').slice(0,150),{type:rec.mime});await storeEvidence(rec.ref,file);count++;}return count;}
async function commitEvidence(ref,file){if(!file?.size)return;try{
 if(runtime.mode==='app'){
  const record=await cloud.uploadFile(file,'evidence');const a=structuredClone(data);a.evidenceIndex={...(a.evidenceIndex||{}),[ref]:record};setData(a,'Đã đính kèm chứng từ cho doanh nghiệp.');
 }else{await storeEvidence(ref,file);notice('Đã lưu chứng từ cho bản xem thử.');}
 }catch(e){notice('Giao dịch đã lưu nhưng chứng từ chưa lưu được: '+e.message,'bad');}}

